foreach(query("SELECT r.kind,r.status,COALESCE(m.archived,0) archived,COALESCE(m.is_read,0) is_read,COALESCE(m.priority,'normal') priority FROM requests r LEFT JOIN request_meta m ON m.request_id=r.id") as $r){if((bool)$r['archived']===($f['archive']==='1')){$tabCounts['all']++;if(isset($tabCounts[$r['kind']]))$tabCounts[$r['kind']]++;}if($r['archived']){$counts['archive']++;continue;}$counts['all']++;if(isset($counts[$r['kind']]))$counts[$r['kind']]++;if(!$r['is_read'])$counts['unread']++;if($r['priority']==='high')$counts['priority']++;if(in_array($r['status'],['Reçue','En cours'],true))$counts['pending']++;}
